  1	package com.thinkaurelius.titan.diskstorage.configuration;
  2	
  3	import com.google.common.base.Preconditions;
  4	import com.google.common.collect.Lists;
  5	import com.thinkaurelius.titan.core.util.ReflectiveConfigOptionLoader;
  6	import org.apache.commons.lang.StringUtils;
  7	import org.apache.commons.lang.builder.HashCodeBuilder;
  8	
  9	import java.util.List;
 10	
 11	/**
 12	 * @author Matthias Broecheler (me@matthiasb.com)
 13	 */
 14	public abstract class ConfigElement {
 15	
 16	    public static final char SEPARATOR = '.';
 17	
 18	    public static final char[] ILLEGAL_CHARS = new char[]{SEPARATOR,' ','\t','#','@','<','>','?','/',';','"','\'',':','+','(',')','*','^','`','~','$','%','|','\\','{','[',']','}'};
 19	
 20	    private final ConfigNamespace namespace;
 21	    private final String name;
 22	    private final String description;
 23	
 24	    public ConfigElement(ConfigNamespace namespace, String name, String description) {
 25	        Preconditions.checkArgument(StringUtils.isNotBlank(name),"Name cannot be empty: %s",name);
 26	        Preconditions.checkArgument(!StringUtils.containsAny(name, ILLEGAL_CHARS),"Name contains illegal character: %s (%s)",name,ILLEGAL_CHARS);
 27	        Preconditions.checkArgument(namespace!=null || this instanceof ConfigNamespace,"Need to specify namespace for ConfigOption");
 28	        Preconditions.checkArgument(StringUtils.isNotBlank(description));
 29	        this.namespace = namespace;
 30	        this.name = name;
 31	        this.description = description;
 32	        if (namespace!=null) namespace.registerChild(this);
 33	    }
 34	
 35	    public ConfigNamespace getNamespace() {
 36	        Preconditions.checkArgument(namespace !=null,"Cannot get namespace of root");
 37	        return namespace;
 38	    }
 39	
 40	    public boolean isRoot() {
 41	        return namespace ==null;
 42	    }
 43	
 44	    public ConfigNamespace getRoot() {
 45	        if (isRoot()) return (ConfigNamespace)this;
 46	        else return getNamespace().getRoot();
 47	    }
 48	
 49	    public String getName() {
 50	        return name;
 51	    }
 52	
 53	    public String getDescription() {
 54	        return description;
 55	    }
 56	
 57	    public abstract boolean isOption();
 58	
 59	    public boolean isNamespace() {
 60	        return !isOption();
 61	    }
 62	
 63	    @Override
 64	    public String toString() {
 65	        return (namespace !=null? namespace.toString()+SEPARATOR:"") + name;
 66	    }
 67	
 68	    @Override
 69	    public int hashCode() {
 70	        return new HashCodeBuilder().append(name).append(namespace).toHashCode();
 71	    }
 72	
 73	    @Override
 74	    public boolean equals(Object oth) {
 75	        if (this==oth) return true;
 76	        else if (oth==null || !getClass().isInstance(oth)) return false;
 77	        ConfigElement c = (ConfigElement)oth;
 78	        return name.equals(c.name) && namespace ==c.namespace;
 79	    }
 80	
 81	    public static String[] getComponents(final String path) {
 82	        return StringUtils.split(path,SEPARATOR);
 83	    }
 84	
 85	    public static String toStringSingle(ConfigElement element) {
 86	        return toStringSingle(element,"");
 87	    }
 88	
 89	    private static String toStringSingle(ConfigElement element, String indent) {
 90	        String result = element.getName();
 91	        if (element.isNamespace()) {
 92	            result = "+ " + result;
 93	            if (((ConfigNamespace)element).isUmbrella())
 94	                result += " [*]";
 95	        } else {
 96	            result = "- " + result;
 97	            ConfigOption option = (ConfigOption)element;
 98	            result+= " [";
 99	            switch (option.getType()) {
100	                case FIXED: result+="f"; break;
101	                case GLOBAL_OFFLINE: result+="g!"; break;
102	                case GLOBAL: result+="g"; break;
103	                case MASKABLE: result+="m"; break;
104	                case LOCAL: result+="l"; break;
105	            }
106	            result+=","+option.getDatatype().getSimpleName();
107	            result+=","+option.getDefaultValue();
108	            result+="]";
109	        }
110	        result = indent + result + "\n" + indent;
111	        String desc = element.getDescription();
112	        result+="\t"+'"'+desc.substring(0, Math.min(desc.length(), 50))+'"';
113	        return result;
114	    }
115	
116	    public static String toString(ConfigElement element) {
117	        //return toStringRecursive(element,"");
118	        return toStringSingle(element, "");
119	    }
120	
121	//    private static String toStringRecursive(ConfigElement element, String indent) {
122	//        String result = toStringSingle(element, indent) + "\n";
123	//        if (element.isNamespace()) {
124	//            ConfigNamespace ns = (ConfigNamespace)element;
125	//            indent += "\t";
126	//            for (ConfigElement child : ns.getChildren()) {
127	//                result += toStringRecursive(child,indent);
128	//            }
129	//        }
130	//        return result;
131	//    }
132	
133	    public static String getPath(ConfigElement element, String... umbrellaElements) {
134	        return getPath(element, false, umbrellaElements);
135	    }
136	
137	    public static String getPath(ConfigElement element, boolean includeRoot, String... umbrellaElements) {
138	        Preconditions.checkNotNull(element);
139	        if (umbrellaElements==null) umbrellaElements = new String[0];
140	        String path = element.getName();
141	        int umbrellaPos = umbrellaElements.length-1;
142	        while (!element.isRoot() && !element.getNamespace().isRoot()) {
143	            ConfigNamespace parent = element.getNamespace();
144	            if (parent.isUmbrella()) {
145	                Preconditions.checkArgument(umbrellaPos>=0,"Missing umbrella element path for element: %s",element);
146	                String umbrellaName = umbrellaElements[umbrellaPos];
147	                Preconditions.checkArgument(!StringUtils.containsAny(umbrellaName,ILLEGAL_CHARS),"Invalid umbrella name provided: %s. Contains illegal chars",umbrellaName);
148	                path = umbrellaName + SEPARATOR + path;
149	                umbrellaPos--;
150	            }
151	            path = parent.getName() + SEPARATOR + path;
152	            element = parent;
153	        }
154	        if (includeRoot) {
155	            // Assumes that roots are not umbrellas
156	            // If roots could be umbrellas, we might have to change the interpretation of umbrellaElements
157	            path = (element.isNamespace() ?
158	                    element.getName() :
159	                    element.getNamespace().getName()) + SEPARATOR + path;
160	        }
161	        //Don't make this check so that we can still access more general config items
162	        Preconditions.checkArgument(umbrellaPos<0,"Found unused umbrella element: %s",umbrellaPos<0?null:umbrellaElements[umbrellaPos]);
163	        return path;
164	    }
165	
166	    public static PathIdentifier parse(ConfigNamespace root, String path) {
167	        Preconditions.checkNotNull(root);
168	        if (StringUtils.isBlank(path)) return new PathIdentifier(root,new String[]{},false);
169	        String[] components = getComponents(path);
170	        Preconditions.checkArgument(components.length>0,"Empty path provided: %s",path);
171	        List<String> umbrellaElements = Lists.newArrayList();
172	        ConfigNamespace parent = root;
173	        ConfigElement last = root;
174	        boolean lastIsUmbrella = false;
175	        for (int i=0;i<components.length;i++) {
176	            if (parent.isUmbrella() && !lastIsUmbrella) {
177	                umbrellaElements.add(components[i]);
178	                lastIsUmbrella = true;
179	            } else {
180	                last = parent.getChild(components[i]);
181	                Preconditions.checkArgument(last!=null,"Unknown configuration element in namespace [%s]: %s",parent.toString(),components[i]);
182	                if (i+1<components.length) {
183	                    Preconditions.checkArgument(last instanceof ConfigNamespace,"Expected namespace at position [%s] of [%s] but got: %s",i,path,last);
184	                    parent = (ConfigNamespace)last;
185	                }
186	                lastIsUmbrella = false;
187	            }
188	        }
189	        return new PathIdentifier(last,umbrellaElements.toArray(new String[umbrellaElements.size()]), lastIsUmbrella);
190	    }
191	
192	    public static class PathIdentifier {
193	
194	        public final ConfigElement element;
195	        public final String[] umbrellaElements;
196	        public final boolean lastIsUmbrella;
197	
198	        private PathIdentifier(ConfigElement element, String[] umbrellaElements, boolean lastIsUmbrella) {
199	            this.lastIsUmbrella = lastIsUmbrella;
200	            Preconditions.checkNotNull(element);
201	            Preconditions.checkNotNull(umbrellaElements);
202	            this.element = element;
203	            this.umbrellaElements = umbrellaElements;
204	        }
205	
206	        public boolean hasUmbrellaElements() {
207	            return umbrellaElements.length>0;
208	        }
209	
210	    }
211	
212	
213	}

