10	/**
11	 * @author Matthias Broecheler (me@matthiasb.com)
12	 */
13	public class ConfigNamespace extends ConfigElement {
14	
15	    private final boolean isUmbrella;
16	    private final Map<String,ConfigElement> children = Maps.newHashMap();
17	
18	    public ConfigNamespace(ConfigNamespace parent, String name, String description, boolean isUmbrella) {
19	        super(parent,name,description);
20	        this.isUmbrella=isUmbrella;
21	    }
22	
23	    public ConfigNamespace(ConfigNamespace parent, String name, String description) {
24	        this(parent,name,description,false);
25	    }
26	
27	    /**
28	     * Wether this namespace is an umbrella namespace, that is, is expects immediate sub-namespaces which are user defined.
29	     * @return
30	     */
31	    public boolean isUmbrella() {
32	        return isUmbrella;
33	    }
34	
35	    /**
36	     * Whether this namespace or any parent namespace is an umbrella namespace.
37	     * @return
38	     */
39	    public boolean hasUmbrella() {
40	        if (isUmbrella()) return true;
41	        if (isRoot()) return false;
42	        return getNamespace().hasUmbrella();
43	    }
44	
45	    @Override
46	    public boolean isOption() {
47	        return false;
48	    }
49	
50	    void registerChild(ConfigElement element) {
51	        Preconditions.checkNotNull(element);
52	        Preconditions.checkArgument(element.getNamespace()==this,"Configuration element registered with wrong namespace");
53	        Preconditions.checkArgument(!children.containsKey(element.getName()),
54	                "A configuration element with the same name has already been added to this namespace: %s",element.getName());
55	        children.put(element.getName(),element);
56	    }
57	
58	    public Iterable<ConfigElement> getChildren() {
59	        return children.values();
60	    }

