import java.util.*;

class Node {
    Node parent;
    String name;
    boolean umbrella;
    Node(Node parent, String name) { this(parent, name, false); }
    Node(Node parent, String name, boolean umbrella) { this.parent = parent; this.name = name; this.umbrella = umbrella; }
    boolean isRoot() { return parent == null; }
    boolean isNamespace() { return true; } // treat all as namespace for this test
}

public class Test {
    static String getPath(Node element, boolean includeRoot, String... umbrellaElements) {
        if (umbrellaElements == null) umbrellaElements = new String[0];
        String path = element.name;
        int umbrellaPos = umbrellaElements.length - 1;
        while (!element.isRoot() && !element.parent.isRoot()) {
            Node parent = element.parent;
            if (parent.umbrella) {
                String umbrellaName = umbrellaElements[umbrellaPos];
                path = umbrellaName + "." + path;
                umbrellaPos--;
            }
            path = parent.name + "." + path;
            element = parent;
        }
        if (includeRoot) {
            path = (element.isNamespace() ? element.name : element.parent.name) + "." + path;
        }
        return path;
    }

    public static void main(String[] args) {
        Node MAPRED_NS = new Node(null, "titanmr");
        Node IOFORMAT_NS = new Node(MAPRED_NS, "ioformat");
        Node GRAPH_CONFIG_KEYS = new Node(IOFORMAT_NS, "conf");

        System.out.println("getPath(GRAPH_CONFIG_KEYS) = " + getPath(GRAPH_CONFIG_KEYS, false));
        System.out.println("getPath(GRAPH_CONFIG_KEYS, true) = " + getPath(GRAPH_CONFIG_KEYS, true));

        Node SCAN_NS = new Node(MAPRED_NS, "scanjob");
        Node SCAN_JOB_CONFIG_KEYS = new Node(SCAN_NS, "conf");
        System.out.println("getPath(SCAN_JOB_CONFIG_KEYS) = " + getPath(SCAN_JOB_CONFIG_KEYS, false));
        System.out.println("getPath(SCAN_JOB_CONFIG_KEYS, true) = " + getPath(SCAN_JOB_CONFIG_KEYS, true));
    }
}
EOF
cd "$TMPDIR/confelementtest" && javac Test.java && java Test

